import{_ as i,l as o,o as e,c as n,v as t,p as s,x as r,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"掩模库与交换","description":"","frontmatter":{"title":"掩模库与交换","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/reticle-library-exchange.md","filePath":"litho/reticle-library-exchange.md","lastUpdated":1789023840000}'),p={name:"litho/reticle-library-exchange.md"};function _(m,a,f,u,E,b){const l=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="掩模库与交换" tabindex="-1">掩模库与交换 <a class="header-anchor" href="#掩模库与交换" aria-label="Permalink to &quot;掩模库与交换&quot;">​</a></h1><div class="epigraph"><p>扫描仪旁的库把多块掩模换成场间几秒。交换慢，产能死；交换脏，缺陷和热漂移一起进。</p><footer>—— 对照 reticle library / reticle stage swap；[掩模台同步](/litho/reticle-stage-sync)</footer></div><p><a href="/litho/wafer-load-prealign">上一课</a>上片。缺口是上版：库、机械手、夹持、条码。本课钉掩模库与交换，不写掩模厂制版。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一层多版（LELE 颜色、切割）要换版。库容量、交换时间、夹持重复性进套刻与产能。 Pellicle 碰撞、颗粒从库落到版上，是轨道缺陷之外的来源。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>条码/RFID 对配方。交换路径最短、气流不直吹版面。夹持力与 <a href="/litho/reticle-clamp">掩模夹持</a> 课（若已写）一致。热：刚从库到曝光，版温未平衡会胀，要等待或补偿。</p>',7)),(e(),s(c,null,{default:r(()=>[h(l,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIB%5B%22%E6%8E%A9%E6%A8%A1%E5%BA%93%22%5D%20--%3E%20ROB%5B%22%E6%8D%A2%E7%89%88%E6%89%8B%22%5D%0A%20%20ROB%20--%3E%20CLAMP%5B%22%E5%A4%B9%E6%8C%81%22%5D%0A%20%20CLAMP%20--%3E%20EXP%5B%22%E6%9B%9D%E5%85%89%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>版在光路里吸收 193 nm 会热胀，库温与机内温差造成第一次场的放大率误差。交换加速度类似台，但负载是版+pellicle。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课机台匹配：换到另一台扫描仪，库里同一块版的放大率指纹不同。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>换版时间是产能；夹持与热是套刻。</li><li>库是缺陷源之一，要管气流与碰撞。</li><li>出处：掩模台课；产能课。</li></ul>',6))])}const P=i(p,[["render",_]]);export{x as __pageData,P as default};
